import React from "react";

import { ProgressDialogStep, SelectorResult, StudioProApi } from "@mendix/extensions-api";

import { createStudioProLogger } from "../../../config/logger";
import { Knowledgebase } from "../../../types/knowledgebase/knowledgebase";
import {
    Collection,
    MxCloudGenAIKeyImportData,
    MxCloudGenAIKnowledgebaseFields,
} from "../../../types/knowledgebase/mxCloudGenAIKnowledgebase";
import { getConstantValue } from "../../../utils/constantUtils";
import { clearKnowledgebaseDetails } from "../../../utils/knowledgebaseUtils";
import {
    decodeAndParseKeyKnowledgebase,
    getCollections,
    invokeResourceAPIKnowledgeBase,
    updateKnowledgeBaseDetailsFromResourcesAPI,
} from "../../../utils/mxCloudGenAIUtils";
import { KeyConstantValidationError, KeyConstantValidationErrors } from "./mxCloudGenAI";

/**
 * Synchronizes the knowledge base's embedding model details details with the MxCloudGenAI
 * resource API.
 *
 * When the API call succeeds, this updates both local state and the persisted
 * model document with embedding model related values derived from the API response.
 * If the API is unavailable, a warning is logged and the existing values are kept.
 */
export const syncModelFromResourceAPI = async (
    studioPro: StudioProApi,
    knowledgebase: Knowledgebase,
    setKnowledgebase: React.Dispatch<React.SetStateAction<Knowledgebase>>,
    updateKnowledgebaseDocument: (model: Knowledgebase) => Promise<void>
): Promise<void> => {
    const logger = createStudioProLogger(studioPro);
    const resourceAPIResponse = await invokeResourceAPIKnowledgeBase(studioPro, knowledgebase);

    if (typeof resourceAPIResponse === "string") {
        logger.warn("MxCloudGenAI resource API unavailable. Could not update model details.");
        return;
    }

    const updatedKnowledgeBase: Knowledgebase = updateKnowledgeBaseDetailsFromResourcesAPI(
        knowledgebase,
        resourceAPIResponse
    );
    const providerFields = knowledgebase.providerFields as MxCloudGenAIKnowledgebaseFields;
    const updatedProviderFields = updatedKnowledgeBase.providerFields as MxCloudGenAIKnowledgebaseFields;
    if (
        providerFields.modelDisplayName !== updatedProviderFields.modelDisplayName ||
        providerFields.modelName !== updatedProviderFields.modelName
    ) {
        setKnowledgebase(updatedKnowledgeBase);
        updateKnowledgebaseDocument(updatedKnowledgeBase).catch((err) =>
            logger.error("Failed to update model document after API response:", err)
        );
    }
};

export const handleImportKeyFromPortal = async (
    studioPro: StudioProApi,
    knowledgebase: Knowledgebase,
    setKnowledgebase: React.Dispatch<React.SetStateAction<Knowledgebase>>,
    setKeyValidationError: React.Dispatch<React.SetStateAction<KeyConstantValidationError | undefined>>,
    updateKnowledgebaseDocument: (model: Knowledgebase) => Promise<void>
) => {
    const logger = createStudioProLogger(studioPro);
    try {
        const mxCloudGenAIKnowledgebaseFields = knowledgebase.providerFields as MxCloudGenAIKnowledgebaseFields;
        const keyValue = await getConstantValue(studioPro, mxCloudGenAIKnowledgebaseFields.key);

        if (!keyValue) {
            throw new Error("No key value found. Please make sure the key constant is correctly configured.");
        }

        // Decode base64 JSON
        const keyData: MxCloudGenAIKeyImportData = decodeAndParseKeyKnowledgebase(studioPro, keyValue);

        if (keyData.type !== "KNOWLEDGE_BASE") {
            throw new Error(
                `Unsupported key type: ${keyData.type}. Only Text Generation keys are currently supported.`
            );
        }

        // Map JSON fields to model attributes
        const updatedMxCloudGenAIKnowledgebaseFields: MxCloudGenAIKnowledgebaseFields = {
            key: mxCloudGenAIKnowledgebaseFields.key,
            keyId: keyData.keyId || "",
            keyName: keyData.keyName || "",
            environment: keyData.environment || "",
            deepLinkURL: keyData.deepLinkUrl || "",
            modelDisplayName: keyData.embeddings.name || "",
            modelName: keyData.embeddings.model || "",
        };

        const updatedKnowledgebase: Knowledgebase = {
            ...knowledgebase,
            name: keyData.name || "",
            providerFields: {
                ...updatedMxCloudGenAIKnowledgebaseFields,
            },
        };

        setKnowledgebase(updatedKnowledgebase);
        updateKnowledgebaseDocument(updatedKnowledgebase);

        await syncModelFromResourceAPI(studioPro, updatedKnowledgebase, setKnowledgebase, updateKnowledgebaseDocument);
    } catch (error) {
        logger.error("Error during MxCloud GenAI key import:", error);
        const errorMessage = "Failed to import MxCloud GenAI Knowledge base key.";
        const errorDetails = String(error);
        const clearedModel = clearKnowledgebaseDetails(knowledgebase);

        await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);

        setKnowledgebase(clearedModel);
        updateKnowledgebaseDocument(clearedModel);
        setKeyValidationError(KeyConstantValidationErrors.NotImported);
    }
};

export async function handleSelectKnowledgebaseKey(
    studioPro: StudioProApi,
    knowledgebase: Knowledgebase
): Promise<Knowledgebase | undefined> {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({
        allowNone: true,
        query: { elementType: "Constants$Constant" },
    });

    if (selectorResult.status === "ok") {
        return {
            ...knowledgebase,
            providerFields: {
                ...knowledgebase.providerFields,
                key: {
                    documentId: selectorResult.selected.id,
                    qualifiedName: selectorResult.selected.module + "." + selectorResult.selected.name,
                },
            },
        };
    }
    if (selectorResult.status === "none") {
        return { ...knowledgebase, providerFields: { ...knowledgebase.providerFields, key: "" } };
    }
}

export async function handleViewCollections(
    studioPro: StudioProApi,
    knowledgebase: Knowledgebase
): Promise<Collection[] | undefined> {
    let collections: Collection[] = [];
    const steps: ProgressDialogStep[] = [
        {
            title: "Getting collections",
            description: "Getting collections",
            action: async () => {
                const result = await getCollections(studioPro, knowledgebase)();

                if (typeof result === "string") {
                    return result; // Error message
                }

                collections = result;

                return true;
            },
        },
    ];
    const progressDialogResult = await studioPro.ui.dialogs.showProgressDialog("Getting collections", steps);
    switch (progressDialogResult.result) {
        case "Success":
            return collections;
        case "UserCancelled":
            return undefined;
        case "Failure": {
            const errorMessage =
                "No connection. Make sure you are connected to the internet and check that a valid key is set as value for the selected constant.";
            const errorDetails = progressDialogResult.failedStep?.error ?? "";
            await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
            return undefined;
        }
    }
}
