import { Knowledgebase, Provider } from "../../types/knowledgebase/knowledgebase";
import { MxCloudGenAIKnowledgebaseFields } from "../../types/knowledgebase/mxCloudGenAIKnowledgebase";
import { createNewMxCloudGenAIKnowledgebaseFields } from "../../utils/knowledgebaseUtils";

export const handleProviderChange =
    (
        knowledgebase: Knowledgebase,
        setKnowledgebase: React.Dispatch<React.SetStateAction<Knowledgebase>>,
        updateKnowledgebaseDocument: (knowledgebase: Knowledgebase) => Promise<void>,
        newProvider: Provider
    ) =>
    async () => {
        // Don't reinitialize if provider fields are already of the correct type
        if (knowledgebase.provider === newProvider && "key" in knowledgebase.providerFields) {
            return;
        }

        // Initialize provider-specific fields when provider is selected
        if (newProvider === "MxCloudGenAI") {
            const newProviderFields: MxCloudGenAIKnowledgebaseFields = createNewMxCloudGenAIKnowledgebaseFields();

            const updatedKnowledgebase = { ...knowledgebase, provider: newProvider, providerFields: newProviderFields };
            setKnowledgebase(updatedKnowledgebase);
            updateKnowledgebaseDocument(updatedKnowledgebase);
        }
    };
